def verify_step3(max_n=5):
    errors = []
    for n in range(1, max_n+1):
        # 正向数列
        forward = list(range(1, n+1))
        # 反向数列
        reverse = list(range(n, 0, -1))
        # 逐项相加
        pairs = [(forward[i], reverse[i]) for i in range(n)]
        sums = [a + b for a, b in pairs]
        # 检查每个和是否为 n+1
        for i, s in enumerate(sums):
            if s != n + 1:
                errors.append((n, i, forward[i], reverse[i], s))
        # 检查括号数量是否为 n
        if len(sums) != n:
            errors.append((n, "括号数量错误", len(sums)))
    if errors:
        print("发现错误：", errors)
    else:
        print(f"Step 3 对 n=1 到 {max_n} 验证通过。")
    return errors

verify_step3(5)

def verify_formula(max_n=10):
    errors = []
    for n in range(1, max_n+1):
        # 实际和
        actual = sum(range(1, n+1))
        # 公式
        formula = n * (n + 1) // 2
        if actual != formula:
            errors.append((n, actual, formula))
    if errors:
        print("发现错误：", errors)
    else:
        print(f"公式对 n=1 到 {max_n} 验证通过。")
    return errors

verify_formula(10)
